-- Athena saved query (Product_B2C_Intl)
-- ID: 12886c66-1516-48ff-b4e3-e0c9cb23b7f3
-- Name: Cohort Deals Final Metrics - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH -- 1) SRP route tuples (Same Day), minimal columns only srp_tuples AS ( SELECT CAST(DATE_TRUNC('day', at_timezone(s.__time, 'Asia/Kolkata')) AS DATE) AS doi, s.mri_session_id, s.route_id, CAST(s.doj AS VARCHAR) AS doj, CASE WHEN s.channel_exp_info IS NULL THEN 'null' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V0') THEN 'V0' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V1') THEN 'V1' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V2') THEN 'V2' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V3') THEN 'V3' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V4') THEN 'V4' ELSE 'others' END AS exp_variant, MAX(CASE WHEN s.cohort_type = 'BOOSTUI' THEN 1 ELSE 0 END) AS is_boost_route FROM "user_interaction"."search_route_details" s WHERE s.__time >= TIMESTAMP '2026-03-31 18:30:00' AND s.__time < TIMESTAMP '2026-04-01 18:30:00' AND s.channel IN ('MOBILE_APP') AND s.os = 'iOS' AND s.tp_channel = 'INVALID' AND s.country = 'IND' AND DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, s."__time")), s.doj) = 0 GROUP BY 1,2,3,4,5 ), -- 2) Session → (doi, variant) and whether session saw any boost (Same Day) session_dim AS ( SELECT doi, mri_session_id, MAX(exp_variant) AS exp_variant, MAX(is_boost_route) AS boost_seen_session FROM srp_tuples GROUP BY 1,2 ), -- 3) Offer tuple route universe: if route boosted anywhere in variant (per day here) offer_tuple_routes AS ( SELECT DISTINCT doi, exp_variant, route_id FROM srp_tuples WHERE is_boost_route = 1 ), offer_tuple_counts AS ( SELECT doi, exp_variant, COUNT(DISTINCT route_id) AS boosted_routeids FROM offer_tuple_routes GROUP BY 1,2 ), -- 4) SL base (Same Day), keep only needed identifiers sl_base AS ( SELECT sld.mri_session_id, sld.route_id, CAST(sld.doj AS VARCHAR) AS doj, sld.__time AS sl_time, sld.mri_uuid, CASE WHEN sld.user_origin LIKE 'BOOSTUI%' THEN 1 ELSE 0 END AS sl_entry_boostui FROM "user_interaction"."seat_layout_details" sld WHERE sld.__time >= TIMESTAMP '2026-03-31 18:30:00' AND sld.__time < TIMESTAMP '2026-04-01 18:30:00' AND sld.os = 'iOS' AND sld.country = 'IND' AND DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, sld."__time")), CAST(sld.doj AS DATE)) = 0 ), -- 5) Aggregate SL at (doi, variant, boost_seen_session) grain to avoid huge distincts later sl_agg AS ( SELECT sd.doi, sd.exp_variant, sd.boost_seen_session, COUNT(DISTINCT sb.mri_uuid) AS overall_sl_clicks, COUNT(DISTINCT sb.mri_session_id) AS overall_sl_sessions, COUNT(DISTINCT CASE WHEN otr.route_id IS NOT NULL THEN sb.mri_uuid END) AS offer_tuple_overall_sl_clicks, COUNT(DISTINCT CASE WHEN otr.route_id IS NOT NULL AND sb.sl_entry_boostui = 1 THEN sb.mri_uuid END) AS offer_tuple_boosted_sl_clicks, COUNT(DISTINCT CASE WHEN otr.route_id IS NOT NULL AND sb.sl_entry_boostui = 0 THEN sb.mri_uuid END) AS offer_tuple_non_boosted_sl_clicks, COUNT(DISTINCT CASE WHEN otr.route_id IS NOT NULL THEN sb.mri_session_id END) AS offer_tuple_overall_sl_sessions, COUNT(DISTINCT CASE WHEN otr.route_id IS NOT NULL AND sb.sl_entry_boostui = 1 THEN sb.mri_session_id END) AS offer_tuple_boosted_sl_sessions, COUNT(DISTINCT CASE WHEN otr.route_id IS NOT NULL AND sb.sl_entry_boostui = 0 THEN sb.mri_session_id END) AS offer_tuple_non_boosted_sl_sessions FROM sl_base sb INNER JOIN session_dim sd ON sd.mri_session_id = sb.mri_session_id LEFT JOIN offer_tuple_routes otr ON otr.doi = sd.doi AND otr.exp_variant = sd.exp_variant AND otr.route_id = sb.route_id GROUP BY 1,2,3 ), -- 6) Confirm base (Same Day) confirm_base AS ( SELECT c.__time AS confirm_time, c.mri_session_id, c.route_id, CAST(c.doj AS VARCHAR) AS doj, c.tin FROM "user_interaction"."confirm_order_details" c WHERE c.__time >= TIMESTAMP '2026-03-31 18:30:00' AND c.__time < TIMESTAMP '2026-04-01 18:30:00' AND c.os = 'iOS' AND c.country = 'IND' AND DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, c."__time")), c.doj) = 0 AND c.status = 200 AND c.tin IS NOT NULL AND c.tin NOT IN ('', 'null') ), -- 7) Attribute each tin to the latest SL before confirm (your existing logic, but minimal columns) confirm_attrib AS ( SELECT * FROM ( SELECT cb.mri_session_id, cb.route_id, cb.doj, cb.tin, COALESCE(sb.sl_entry_boostui, 0) AS sl_entry_boostui, -- if no prior SL match, treat as 0 ROW_NUMBER() OVER ( PARTITION BY cb.tin ORDER BY sb.sl_time DESC ) AS rn FROM confirm_base cb LEFT JOIN sl_base sb ON sb.mri_session_id = cb.mri_session_id AND sb.route_id = cb.route_id AND sb.sl_time < cb.confirm_time ) x WHERE rn = 1 ), confirm_agg AS ( SELECT sd.doi, sd.exp_variant, sd.boost_seen_session, COUNT(DISTINCT ca.tin) AS overall_tins, COUNT(DISTINCT ca.mri_session_id) AS overall_confirm_sessions, COUNT(DISTINCT CASE WHEN otr.route_id IS NOT NULL THEN ca.tin END) AS offer_tuple_overall_tins, COUNT(DISTINCT CASE WHEN otr.route_id IS NOT NULL AND ca.sl_entry_boostui = 1 THEN ca.tin END) AS offer_tuple_boosted_tins, COUNT(DISTINCT CASE WHEN otr.route_id IS NOT NULL AND ca.sl_entry_boostui = 0 THEN ca.tin END) AS offer_tuple_non_boosted_tins, COUNT(DISTINCT CASE WHEN otr.route_id IS NOT NULL THEN ca.mri_session_id END) AS offer_tuple_overall_confirm_sessions, COUNT(DISTINCT CASE WHEN otr.route_id IS NOT NULL AND ca.sl_entry_boostui = 1 THEN ca.mri_session_id END) AS offer_tuple_boosted_confirm_sessions, COUNT(DISTINCT CASE WHEN otr.route_id IS NOT NULL AND ca.sl_entry_boostui = 0 THEN ca.mri_session_id END) AS offer_tuple_non_boosted_confirm_sessions FROM confirm_attrib ca INNER JOIN session_dim sd ON sd.mri_session_id = ca.mri_session_id LEFT JOIN offer_tuple_routes otr ON otr.doi = sd.doi AND otr.exp_variant = sd.exp_variant AND otr.route_id = ca.route_id GROUP BY 1,2,3 ), -- 8) Search sessions (from SRP) at the same final grain srp_sessions AS ( SELECT sd.doi, sd.exp_variant, sd.boost_seen_session, COUNT(DISTINCT sd.mri_session_id) AS overall_search_sessions FROM session_dim sd GROUP BY 1,2,3 ) SELECT ss.doi, ss.exp_variant, 'Overall' AS "user type", CASE WHEN ss.boost_seen_session = 1 THEN 'Seen' ELSE 'Not Seen' END AS "BOOSTUI seen", COALESCE(otc.boosted_routeids, 0) AS boosted_routeids, -- Clicks / SL COALESCE(sa.overall_sl_clicks, 0) AS "overall sl clicks", COALESCE(sa.offer_tuple_boosted_sl_clicks, 0) AS "Offer Tuple boosted sl clicks", COALESCE(sa.offer_tuple_non_boosted_sl_clicks, 0) AS "Offer Tuple non boosted sl clicks", COALESCE(sa.offer_tuple_overall_sl_clicks, 0) AS "Offer Tuple overall sl clicks", -- Orders / tins COALESCE(ca.overall_tins, 0) AS "overall tins", COALESCE(ca.offer_tuple_boosted_tins, 0) AS "Offer Tuple boosted tins", COALESCE(ca.offer_tuple_non_boosted_tins, 0) AS "Offer Tuple non boosted tins", COALESCE(ca.offer_tuple_overall_tins, 0) AS "Offer Tuple overall tins", -- Traffic / sessions ss.overall_search_sessions AS "overall search sessions", COALESCE(sa.overall_sl_sessions, 0) AS "overall sl sessions", COALESCE(sa.offer_tuple_boosted_sl_sessions, 0) AS "Offer Tuple boosted sl sessions", COALESCE(sa.offer_tuple_non_boosted_sl_sessions, 0) AS "Offer Tuple non boosted sl sessions", COALESCE(sa.offer_tuple_overall_sl_sessions, 0) AS "Offer Tuple overall sl sessions", COALESCE(ca.overall_confirm_sessions, 0) AS "overall confirm sessions", COALESCE(ca.offer_tuple_boosted_confirm_sessions, 0) AS "Offer Tuple boosted confirm sessions", COALESCE(ca.offer_tuple_non_boosted_confirm_sessions, 0) AS "Offer Tuple non boosted confirm sessions", COALESCE(ca.offer_tuple_overall_confirm_sessions, 0) AS "Offer Tuple overall confirm sessions" FROM srp_sessions ss LEFT JOIN offer_tuple_counts otc ON otc.doi = ss.doi AND otc.exp_variant = ss.exp_variant LEFT JOIN sl_agg sa ON sa.doi = ss.doi AND sa.exp_variant = ss.exp_variant AND sa.boost_seen_session = ss.boost_seen_session LEFT JOIN confirm_agg ca ON ca.doi = ss.doi AND ca.exp_variant = ss.exp_variant AND ca.boost_seen_session = ss.boost_seen_session WHERE ss.exp_variant IN ('V0','V1','V2') ORDER BY 1,2,4;
